def mold_subset(packet):
    # Generic MoldUDP64 wrapper subset; message data is opaque, not assumed ITCH A.
    if type(packet) is not bytes or not 20<=len(packet)<=256:
        raise ValueError("invalid datagram bounds")
    if packet[:10]!=b"SESSION001":
        raise ValueError("unexpected configured session")
    sequence=int.from_bytes(packet[10:18],"big")
    count=int.from_bytes(packet[18:20],"big")
    if not 1<=sequence<=1000:
        raise ValueError("own sequence bound")
    if count in (0,65535):
        if len(packet)!=20:raise ValueError("marker has trailing data")
        return "heartbeat" if count==0 else "end",sequence,[]
    if count>4 or sequence+count-1>1000:
        raise ValueError("own packet count or sequence bound")
    cursor=20
    messages=[]
    for index in range(count):
        if cursor+2>len(packet):raise ValueError("truncated length")
        size=int.from_bytes(packet[cursor:cursor+2],"big")
        cursor+=2
        if size>64 or cursor+size>len(packet):raise ValueError("invalid message length")
        messages.append((sequence+index,packet[cursor:cursor+size]))
        cursor+=size
    if cursor!=len(packet):raise ValueError("trailing bytes")
    return "data",sequence,messages

header=b"SESSION001"+(7).to_bytes(8,"big")
print(mold_subset(header+(2).to_bytes(2,"big")+b"\x00\x01A\x00\x01B"))
print(mold_subset(header+b"\x00\x00"))
print(mold_subset(header+b"\xff\xff"))

