def decode_packets(packets):
    expected = 1
    live = {}
    shares = 0
    lines = []
    for text in packets:
        if len(text) % 2 or len(text) < 10:
            lines.append('ERR LENGTH -')
            continue
        data = bytes.fromhex(text)
        sequence = int.from_bytes(data[:4], 'big')
        if sequence < expected:
            lines.append(f'DUP {sequence}')
            continue
        if sequence > expected:
            lines.append(f'GAP {expected} {sequence - 1}')
        expected = sequence + 1
        kind = data[4:5]
        if kind not in [b'A', b'X', b'E']:
            lines.append(f'ERR TYPE {sequence}')
            continue
        if len(data) != (22 if kind == b'A' else 17):
            lines.append(f'ERR LENGTH {sequence}')
            continue
        if kind == b'A' and data[13:14] not in [b'B', b'S']:
            lines.append(f'ERR TYPE {sequence}')
            continue
        identifier = int.from_bytes(data[5:13], 'big')
        offset = 14 if kind == b'A' else 13
        quantity = int.from_bytes(data[offset:offset + 4], 'big')
        if kind == b'A':
            if identifier in live:
                lines.append(f'ERR DUPID {sequence}')
            else:
                live[identifier] = quantity
        elif identifier not in live:
            lines.append(f'ERR UNKNOWN {sequence}')
        elif quantity > live[identifier]:
            lines.append(f'ERR OVERFLOW {sequence}')
        else:
            live[identifier] -= quantity
            if live[identifier] == 0:
                del live[identifier]
            if kind == b'E':
                shares += quantity
    return lines + [f'BOOK {len(live)}', f'SHARES {shares}']

